def _design(stress, feat, dt, t, logtau, jac=False):
    tau = np.exp(logtau)
    d = _memory(stress, dt, tau, jac)
    if jac:
        d, dd = d
    u = t[:, None] / tau
    f = -np.expm1(-u)
    curve = np.concatenate((d[:, None, :] * f, feat[:, None, :] * t[None, :, None]), axis=2)
    A = np.concatenate((curve, np.c_[d / tau, feat][:, None, :]), axis=1)
    if not jac:
        return A
    dcurve = dd[:, None, :] * f - d[:, None, :] * (u * np.exp(-u))
    return (A, np.concatenate((dcurve, ((dd - d) / tau)[:, None, :]), axis=1))

def _with_prior(x, y, fits, prior):
    gain, bias = prior
    if not len(x):
        return prior
    offsets = y - gain * x - bias
    center = np.median(offsets)
    agreeing = np.abs(offsets - center) <= 0.004
    if agreeing.sum() > len(x) // 2 and (len(x) > 1 or abs(center) < 0.1):
        bias += np.median(offsets[agreeing])
    else:
        i = np.argmin(np.abs(offsets))
        if abs(offsets[i]) < 0.1:
            bias += offsets[i]
    for fit, count, span in fits:
        if count >= 3 and span >= 0.4 and (abs(fit[0] - gain) <= 0.01) and (abs(fit[1] - bias) <= 0.01):
            return fit
    return (gain, bias)
